import{S as n,o as t,c,a9 as d,B as s}from"./chunks/framework.DxG24V0C.js";const r="/agentsrc/images/codex/01-macro-topology.svg",u=JSON.parse('{"title":"Codex 全景：系统级 Agent 的架构与分层","description":"","frontmatter":{},"headers":[],"relativePath":"codex/01-overview.md","filePath":"codex/01-overview.md","lastUpdated":1788847143000}'),i={name:"codex/01-overview.md"},h=Object.assign(i,{setup(l){const o=[{question:"用户通过 npm 安装的 @openai/codex 包，其在系统架构中的真实角色是什么？",options:["包含所有业务逻辑的 Node.js 核心引擎，直接负责调度模型","一个 JavaScript 壳，检测平台并 spawn 预安装的 native 二进制","通过 WebAssembly 编译的 Rust 运行时，在 V8 引擎内执行","负责与 VS Code 插件通信的中间件，处理所有的 JSON-RPC"],correct:1,explanation:"npm 包只是一个分发渠道和启动壳。它的作用是检测当前操作系统架构，定位到由 optional dependencies 提前安装好的 native 二进制文件并启动它，所有核心逻辑都在 Rust 侧。"},{question:"Codex 的主循环（submission_loop）采用了哪种并发设计模式？",options:["基于 async generator 的单线程轮询模式，按顺序让出控制权","基于 Channel 消息传递的 Reactor 模式，事件驱动任务流转","基于多进程共享内存的轮询模式，通过锁机制同步状态数据","基于定时器的定时轮询模式，每隔固定时间检查是否有新输入"],correct:1,explanation:"Codex 采用了基于 Channel 的 Reactor 模式。外部输入被打包成 Op 消息放入 Channel，submission_loop 在后台监听并分发事件，这与 Claude Code 的 async generator 轮询模式有本质区别。"},{question:"在 Codex 的主链路中，当 submission_loop 接收到 Op::UserInput 消息后，系统是如何处理任务调度的？",options:["将新任务加入队列，等待当前任务执行完毕后再按顺序执行","直接在当前线程中同步执行新任务，阻塞后续的所有消息接收","终止当前可能正在运行的旧任务，然后启动一个新的 SessionTask","忽略新任务并向用户报错，直到当前对话轮次完全结束"],correct:2,explanation:"在 user_input_or_turn 流程中，系统会先 abort 掉当前正在运行的旧任务，然后通过 spawn_task(RegularTask::new()) 启动新任务。这种互斥机制保证了状态的一致性。"},{question:"Codex 架构中，负责跨平台 OS 级沙箱（如 Landlock/Seatbelt）和指令策略拦截的模块属于哪个核心分层？",options:["核心中枢层，与对话上下文组装和 Token 预算管理强耦合在一起","工具与扩展层，作为动态工具注册和 MCP 协议解析的核心组成部分","安全与沙箱层，直接调用操作系统底层机制从物理层面阻断恶意操作","IDE 协议层，通过 JSON-RPC 拦截并过滤编辑器发来的所有执行指令"],correct:2,explanation:"沙箱和指令策略（codex-sandboxing, codex-execpolicy）是 Codex 的重武器，独立于核心引擎和工具层，通过 OS 底层机制提供物理级别的安全隔离。"},{question:"Codex 在整体架构设计上，最底层的核心假设是什么？",options:["信任模型生成的代码，重点优化单进程内的执行效率与系统资源占用","假设用户环境是绝对安全的，Agent 仅作为轻量辅助脚本提供代码建议","建立在不信任的假设上，既不信任模型幻觉也不信任单一进程的稳定性","假设所有工具都通过远程网络调用，因此将网络并发作为最高优先级"],correct:2,explanation:"Codex 的架构（OS 级沙箱、拆分独立的 CLI/TUI/AppServer 二进制）都是为了防范模型幻觉和进程崩溃，体现了典型的“系统级软件”防范思维。"}];return(p,e)=>{const a=n("Quiz");return t(),c("div",null,[e[0]||(e[0]=d("",34)),s(a,{questions:o})])}}});export{u as __pageData,h as default};
